 95	    /**
 96	     * The Java type that carries self, a value of the declaring type named t, or null: a type of
 97	     * FortressLibrary or FortressBuiltin, whose names no program can give its own types, that javaFor
 98	     * names, or the object Int, Long, UnsignedLong, Float or BigNum.  Read by its name alone,
 99	     * FlatString or JavaString, a name that a program can give its own type, carries no self; the
100	     * loader reads the declaring type through javaForSelf(FType), which carries the library's own
101	     * FlatString, told by the component that declares it.
102	     */
103	    static Class<?> javaForSelf(String t) {
104	        if (t == null || t.equals("FlatString") || t.equals("JavaString")) return null;
105	        if (t.equals("Int")) return int.class;
106	        if (t.equals("Long") || t.equals("UnsignedLong")) return long.class;
107	        if (t.equals("Float")) return double.class;
108	        if (t.equals("BigNum")) return BigInteger.class;
109	        Class<?> c = javaFor(t);
110	        return c == void.class ? null : c;
111	    }
