148	    /**
149	     * The helper that the string s names for the declaration defn, or an error message.  Among the
150	     * class's public static methods of that name, it takes the one whose parameters are the
151	     * declaration's, self first where the declaration has one (a functional method), or one more
152	     * in front for a dotted method's self, at the Java types that carry the declared types.
153	     */
154	    static Object find(String s, Applicable defn) {
155	        return find(s, defn, null);
156	    }
