158	    /**
159	     * As find(s, defn), where the declaration is a method of the type declarer, whose value
160	     * is self: it refuses a declarer that no Java type carries, and takes only an overload whose
161	     * first Java parameter is the declarer's carrier.
162	     */
163	    static Object find(String s, Applicable defn, FType declarer) {
164	        int dot = s.lastIndexOf('.');
165	        String cls = s.substring(0, dot), name = s.substring(dot + 1);
166	        Class<?> c;
167	        try { c = Class.forName(cls); }
168	        catch (ClassNotFoundException e) { return "Native helper class " + cls + " not found."; }
169	        List<Method> named = new ArrayList<Method>();
170	        for (Method x : c.getMethods())
171	            if (x.getName().equals(name) && Modifier.isStatic(x.getModifiers())) named.add(x);
172	        if (named.isEmpty()) return "Native helper " + s + " names no static method of " + cls + ".";
173	        List<Class<?>> want = new ArrayList<Class<?>>();
174	        boolean hasSelf = false;
175	        for (Param p : NodeUtil.getParams(defn)) {
176	            String pn = p.getName().getText();
177	            if (pn.equals("self")) { hasSelf = true; continue; }
178	            Class<?> j = javaForParameter(p.getIdType().isSome() ? typeName(p.getIdType().unwrap()) : null);
179	            if (j == null || j == void.class)
180	                return "Native helper " + s + ": no Java type carries the declared type of parameter " + pn + ".";
181	            want.add(j);
182	        }
183	        Class<?> res = null;    // a declaration without a result type is refused by NativeApp.init
184	        if (hasResultType(defn)) {
185	            res = javaFor(declaredResult(defn));
186	            if (res == null) return "Native helper " + s + ": no Java type carries the declared result type.";
187	        }
188	        Class<?> selfJava = null;
189	        if (declarer != null) {
190	            selfJava = javaForSelf(declarer);
191	            if (selfJava == null)
192	                return "Native helper " + s + ": no Java type carries " + declarer.getName() + ", the type of self.";
193	        }
194	        List<Method> fits = new ArrayList<Method>();
195	        for (Method x : named) {
196	            Class<?>[] xs = x.getParameterTypes();
197	            int off = xs.length - want.size();          // 1: self first
198	            if (off < 0 || off > 1 || ((hasSelf || selfJava != null) && off != 1)) continue;
199	            boolean ok = (res == null || x.getReturnType() == res)
200	                         && (x.getReturnType() == void.class || carried(x.getReturnType()));
201	            for (int i = 0; ok && i < xs.length; i++) {
202	                if (!carried(xs[i])) ok = false;
203	                else if (i >= off && xs[i] != want.get(i - off)) ok = false;
204	            }
205	            if (ok && selfJava != null && xs[0] != selfJava) ok = false;
206	            if (ok) fits.add(x);
207	        }
208	        if (fits.size() == 1) return fits.get(0);
209	        if (fits.isEmpty()) return "Native helper " + s + " has no overload that fits the declaration's types.";
210	        return "Native helper " + s + " has " + fits.size() + " overloads that fit the declaration's types.";
211	    }
