229	    /** A function, or a functional method with its self among the arguments: self goes first. */
230	    public FValue applyToArgs(List<FValue> args) {
231	        if (selfAt <= 0) return call(args);
232	        List<FValue> all = new ArrayList<FValue>(args);
233	        all.add(0, all.remove(selfAt));
234	        return call(all);
