245	    private FValue call(List<FValue> args) {
246	        if (args.size() != ps.length) return error("Native " + m + " given " + args.size() + " arguments");
247	        Object[] xs = new Object[ps.length];
248	        for (int i = 0; i < ps.length; i++) xs[i] = unbox(ps[i], args.get(i));
249	        try {
250	            return box(m.getReturnType(), result, m.invoke(null, xs));
251	        }
252	        catch (InvocationTargetException e) {
253	            Throwable t = e.getCause();
254	            FortressError f = raised(t);
255	            if (f != null) throw f;
256	            if (t instanceof RuntimeException) throw (RuntimeException) t;
257	            if (t instanceof Error) throw (Error) t;
258	            return error(t.toString());
259	        }
260	        catch (IllegalAccessException e) {
261	            return error(e.toString());
262	        }
263	    }
