267	    /** A helper's Utility.makeFortressException("fortress.<Api>$<Name>") names a compiled class;
268	        under walk it becomes the library's own exception object <Name>. */
269	    static FortressError raised(Throwable t) {
270	        if (!(t instanceof FortressImplementationError) || t.getMessage() == null) return null;
271	        Matcher x = RAISE.matcher(t.getMessage());
272	        if (!x.matches()) return null;
273	        return new FortressError((FObject) Driver.getFortressLibrary().getRootValue(x.group(1)));
274	    }
