276	    static Object unbox(Class<?> c, FValue v) {
277	        if (c == int.class) return v instanceof FChar ? ((FChar) v).getChar() : v.getInt();
278	        if (c == long.class) return v.getLong();
279	        if (c == double.class) return v.getFloat();
280	        if (c == float.class) return (float) v.getFloat();
281	        if (c == boolean.class) return ((FBool) v).getBool();
282	        if (c == String.class) return v.getString();
283	        if (c == BigInteger.class) return v.getBigInteger();
284	        return error("No interpreter value for a Java " + c.getName());
285	    }
