287	    /** The result at the declared type: int as ZZ32, NN32 or Char; long as ZZ64 or NN64. */
288	    static FValue box(Class<?> c, String declared, Object r) {
289	        if (c == void.class) return FVoid.V;
290	        if (c == int.class) {
291	            int i = (Integer) r;
292	            if ("NN32".equals(declared)) return FNN32.make(i);
293	            if ("Char".equals(declared)) return FChar.make(i);
294	            return FInt.make(i);
295	        }
296	        if (c == long.class) {
297	            long l = (Long) r;
298	            if ("NN64".equals(declared)) return FNN64.make(l);
299	            return FLong.make(l);
300	        }
301	        if (c == double.class) return FFloat.make((Double) r);
302	        if (c == float.class) return FRR32.make((Float) r);
303	        if (c == boolean.class) return FBool.make((Boolean) r);
304	        if (c == String.class) return FString.make((String) r);
305	        if (c == BigInteger.class) return FBigNum.make((BigInteger) r);
306	        return error("No interpreter value for a Java " + c.getName());
307	    }
